  \uses{def:covariation}
The covariation $\langle M, N \rangle$ of local martingales $M$ and $N$ is cadlag.
\end{lemma}

\begin{proof}
  \uses{lem:cadlag_quadraticVariation}

\end{proof}


\begin{lemma}\label{lem:covariation_zero}
  \uses{def:covariation}
$\langle M, N \rangle_0 = 0$~.
\end{lemma}

\begin{proof}
